using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using UAF.Domain.Entities;
using UAF.Infrastructure.Identity;
namespace UAF.Infrastructure.Persistence.Configurations;
public sealed class FeeHeadConfiguration:IEntityTypeConfiguration<FeeHead>
{ public void Configure(EntityTypeBuilder<FeeHead>b){b.ToTable("FeeHeads");b.HasKey(x=>x.Id);b.Property(x=>x.Code).HasMaxLength(30).IsRequired();b.Property(x=>x.Name).HasMaxLength(120).IsRequired();b.HasIndex(x=>x.Code).IsUnique();} }
public sealed class FeeStructureConfiguration:IEntityTypeConfiguration<FeeStructure>
{ public void Configure(EntityTypeBuilder<FeeStructure>b){b.ToTable("FeeStructures");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(120).IsRequired();b.Property(x=>x.CurrencyCode).HasMaxLength(3).IsRequired();b.HasIndex(x=>new{x.AcademicProgramId,x.AcademicSessionId,x.SemesterNumber}).IsUnique();b.HasOne<AcademicProgram>().WithMany().HasForeignKey(x=>x.AcademicProgramId).OnDelete(DeleteBehavior.Restrict);b.HasOne<AcademicSession>().WithMany().HasForeignKey(x=>x.AcademicSessionId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.FeeStructureId).OnDelete(DeleteBehavior.Cascade);} }
public sealed class FeeStructureItemConfiguration:IEntityTypeConfiguration<FeeStructureItem>
{ public void Configure(EntityTypeBuilder<FeeStructureItem>b){b.ToTable("FeeStructureItems");b.HasKey(x=>x.Id);b.Property(x=>x.Amount).HasPrecision(18,2);b.HasIndex(x=>new{x.FeeStructureId,x.FeeHeadId}).IsUnique();b.HasOne(x=>x.FeeHead).WithMany().HasForeignKey(x=>x.FeeHeadId).OnDelete(DeleteBehavior.Restrict);} }
public sealed class StudentFeeAccountConfiguration:IEntityTypeConfiguration<StudentFeeAccount>
{ public void Configure(EntityTypeBuilder<StudentFeeAccount>b){b.ToTable("StudentFeeAccounts");b.HasKey(x=>x.Id);b.HasIndex(x=>x.StudentId).IsUnique();b.HasOne<Student>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict);} }
public sealed class FeeChallanConfiguration:IEntityTypeConfiguration<FeeChallan>
{ public void Configure(EntityTypeBuilder<FeeChallan>b){b.ToTable("FeeChallans");b.HasKey(x=>x.Id);b.Property(x=>x.ChallanNumber).HasMaxLength(60).IsRequired();b.Property(x=>x.Subtotal).HasPrecision(18,2);b.Property(x=>x.LateFeeAmount).HasPrecision(18,2);b.Property(x=>x.CurrencyCode).HasMaxLength(3).IsRequired();b.Property(x=>x.Status).HasConversion<int>();b.HasIndex(x=>x.ChallanNumber).IsUnique();b.HasOne(x=>x.StudentFeeAccount).WithMany().HasForeignKey(x=>x.StudentFeeAccountId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.IssuedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasMany<FeeChallanLine>().WithOne().HasForeignKey(x=>x.ChallanId).OnDelete(DeleteBehavior.Cascade);} }
public sealed class FeeChallanLineConfiguration:IEntityTypeConfiguration<FeeChallanLine>
{ public void Configure(EntityTypeBuilder<FeeChallanLine>b){b.ToTable("FeeChallanLines");b.HasKey(x=>x.Id);b.Property(x=>x.FeeHeadCode).HasMaxLength(30).IsRequired();b.Property(x=>x.FeeHeadName).HasMaxLength(120).IsRequired();b.Property(x=>x.Amount).HasPrecision(18,2);b.HasOne<FeeHead>().WithMany().HasForeignKey(x=>x.FeeHeadId).OnDelete(DeleteBehavior.Restrict);} }
public sealed class FeePaymentConfiguration:IEntityTypeConfiguration<FeePayment>
{ public void Configure(EntityTypeBuilder<FeePayment>b){b.ToTable("FeePayments");b.HasKey(x=>x.Id);b.Property(x=>x.Amount).HasPrecision(18,2);b.Property(x=>x.Method).HasMaxLength(30).IsRequired();b.Property(x=>x.ReferenceNumber).HasMaxLength(100).IsRequired();b.Property(x=>x.VerificationRemarks).HasMaxLength(1000);b.Property(x=>x.Status).HasConversion<int>();b.HasIndex(x=>new{x.ChallanId,x.ReferenceNumber}).IsUnique();b.HasOne(x=>x.Challan).WithMany().HasForeignKey(x=>x.ChallanId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.RecordedByUserId).OnDelete(DeleteBehavior.Restrict);b.HasOne<ApplicationUser>().WithMany().HasForeignKey(x=>x.VerifiedByUserId).OnDelete(DeleteBehavior.Restrict);} }